export function liveNewsroomFeed() {
  let intervalId =
    null


  let initialTimeoutId =
    null


  return {
    name:
      'geographic-live-newsroom-background',


    configureServer(
      server
    ) {
      // --------------------------------------------------------
      // PUBLIC PUBLISHED NEWS
      // --------------------------------------------------------
      //
      // GET:
      //   /api/geographic/toronto/news/published
      //   /api/geographic/toronto/news/published?status=archive
      //   /api/geographic/toronto/news/published?status=all
      //
      // The public map will use status=live (the default).
      //
      // --------------------------------------------------------

      server.middlewares.use(
        '/api/geographic/toronto/news/published',

        async (
          req,
          res,
          next
        ) => {
          if (
            req.method !==
              'GET'
          ) {
            next()
            return
          }


          try {
            const url =
              new URL(
                req.url ||
                '/',
                'http://localhost'
              )


            const status =
              cleanText(
                url.searchParams.get(
                  'status'
                )
              ) ||
              'live'


            const records =
              await getPublishedNewsRecords({
                status,
              })


            sendJson(
              res,
              200,
              {
                ok:
                  true,

                status,

                count:
                  records.length,

                updatedAt:
                  store.updatedAt,

                records,
              }
            )
          }
          catch (
            error
          ) {
            sendJson(
              res,
              500,
              {
                ok:
                  false,

                records:
                  [],

                error:
                  String(
                    error?.message ||
                    error
                  ),
              }
            )
          }
        }
      )


      // --------------------------------------------------------
      // ADMIN PUBLISHED NEWS UPSERT
      // --------------------------------------------------------
      //
      // POST:
      //   /api/geographic/toronto/newsroom/published/upsert
      //
      // Body:
      //   { record: {...} }
      //   { records: [{...}, {...}] }
      //
      // This route lives under /newsroom/ so the existing Admin
      // server authentication protects mutations.
      //
      // --------------------------------------------------------

      server.middlewares.use(
        '/api/geographic/toronto/newsroom/published/upsert',

        async (
          req,
          res,
          next
        ) => {
          if (
            req.method !==
              'POST'
          ) {
            next()
            return
          }


          try {
            const body =
              await readJsonBody(
                req
              )


            const incoming =
              Array.isArray(
                body.records
              )
                ? body.records
                : (
                    body.record
                      ? [
                          body.record,
                        ]
                      : []
                  )


            if (
              incoming.length ===
                0
            ) {
              sendJson(
                res,
                400,
                {
                  ok:
                    false,

                  error:
                    'Missing published NEWS record.',
                }
              )

              return
            }


            const records =
              []


            for (
              const record
              of incoming
            ) {
              records.push(
                await upsertPublishedNewsRecord({
                  record,

                  archiveReason:
                    body.archiveReason ||
                    '',
                })
              )
            }


            sendJson(
              res,
              200,
              {
                ok:
                  true,

                count:
                  records.length,

                records,
              }
            )
          }
          catch (
            error
          ) {
            sendJson(
              res,
              400,
              {
                ok:
                  false,

                error:
                  String(
                    error?.message ||
                    error
                  ),
              }
            )
          }
        }
      )


      // --------------------------------------------------------
      // ADMIN ARCHIVE / REMOVE FROM LIVE MAP
      // --------------------------------------------------------
      //
      // POST:
      //   /api/geographic/toronto/newsroom/published/archive
      //
      // This NEVER deletes the historical record. It only sets
      // active:false and records archivedAt/archiveReason.
      //
      // --------------------------------------------------------

      server.middlewares.use(
        '/api/geographic/toronto/newsroom/published/archive',

        async (
          req,
          res,
          next
        ) => {
          if (
            req.method !==
              'POST'
          ) {
            next()
            return
          }


          try {
            const body =
              await readJsonBody(
                req
              )


            const record =
              await archivePublishedNewsRecord({
                id:
                  body.id ||
                  body.record?.id ||
                  '',

                externalId:
                  body.externalId ||
                  body.record?.externalId ||
                  '',

                record:
                  body.record ||
                  null,

                reason:
                  body.reason ||
                  'removed-from-live-map',
              })


            if (
              !record
            ) {
              sendJson(
                res,
                404,
                {
                  ok:
                    false,

                  error:
                    'Published NEWS record not found.',
                }
              )

              return
            }


            sendJson(
              res,
              200,
              {
                ok:
                  true,

                record,
              }
            )
          }
          catch (
            error
          ) {
            sendJson(
              res,
              400,
              {
                ok:
                  false,

                error:
                  String(
                    error?.message ||
                    error
                  ),
              }
            )
          }
        }
      )


      server.middlewares.use(
        '/api/geographic/toronto/newsroom/pending',

        async (
          req,
          res,
          next
        ) => {
          if (
            req.method !==
              'GET'
          ) {
            next()
            return
          }


          try {
            const records =
              await pendingEvents()


            sendJson(
              res,
              200,
              {
                ok:
                  true,

                count:
                  records.length,

                updatedAt:
                  store.updatedAt,

                records,
              }
            )
          }
          catch (
            error
          ) {
            sendJson(
              res,
              500,
              {
                ok:
                  false,

                records:
                  [],

                error:
                  String(
                    error?.message ||
                    error
                  ),
              }
            )
          }
        }
      )


      server.middlewares.use(
        '/api/geographic/toronto/newsroom/sync',

        async (
          req,
          res,
          next
        ) => {
          if (
            req.method !==
              'POST'
          ) {
            next()
            return
          }


          try {
            const result =
              await syncTorontoLiveNewsroom()


            sendJson(
              res,
              200,
              result
            )
          }
          catch (
            error
          ) {
            sendJson(
              res,
              500,
              {
                ok:
                  false,

                error:
                  String(
                    error?.message ||
                    error
                  ),
              }
            )
          }
        }
      )


      server.middlewares.use(
        '/api/geographic/toronto/newsroom/ack',

        async (
          req,
          res,
          next
        ) => {
          if (
            req.method !==
              'POST'
          ) {
            next()
            return
          }


          try {
            const body =
              await readJsonBody(
                req
              )


            const changed =
              await acknowledgeEvents({
                ids:
                  body.ids,

                outcome:
                  body.outcome,

                editorialRecord:
                  body.record ||
                  null,
              })


            sendJson(
              res,
              200,
              {
                ok:
                  true,

                changed,
              }
            )
          }
          catch (
            error
          ) {
            sendJson(
              res,
              400,
              {
                ok:
                  false,

                error:
                  String(
                    error?.message ||
                    error
                  ),
              }
            )
          }
        }
      )


      server.middlewares.use(
        '/api/geographic/toronto/newsroom/log',

        async (
          req,
          res,
          next
        ) => {
          if (
            req.method !==
              'POST'
          ) {
            next()
            return
          }


          try {
            const body =
              await readJsonBody(
                req
              )


            const record =
              await logManualEditorialAction({
                action:
                  body.action,

                record:
                  body.record ||
                  {},
              })


            sendJson(
              res,
              200,
              {
                ok:
                  true,

                record,
              }
            )
          }
          catch (
            error
          ) {
            sendJson(
              res,
              400,
              {
                ok:
                  false,

                error:
                  String(
                    error?.message ||
                    error
                  ),
              }
            )
          }
        }
      )


      server.middlewares.use(
        '/api/geographic/toronto/newsroom/ledger.csv',

        async (
          req,
          res,
          next
        ) => {
          if (
            req.method !==
              'GET'
          ) {
            next()
            return
          }


          try {
            await ensureLedgerHeader()


            const csv =
              await readFile(
                NEWS_LEDGER_PATH,
                'utf8'
              )


            res.statusCode =
              200


            res.setHeader(
              'Content-Type',
              'text/csv; charset=utf-8'
            )


            res.setHeader(
              'Content-Disposition',
              'inline; filename="toronto-news-ledger.csv"'
            )


            res.setHeader(
              'Cache-Control',
              'no-store'
            )


            res.end(
              csv
            )
          }
          catch (
            error
          ) {
            sendJson(
              res,
              500,
              {
                ok:
                  false,

                error:
                  String(
                    error?.message ||
                    error
                  ),
              }
            )
          }
        }
      )


      server.middlewares.use(
        '/api/geographic/toronto/newsroom/status',

        async (
          req,
          res,
          next
        ) => {
          if (
            req.method !==
              'GET'
          ) {
            next()
            return
          }


          await ensureLoaded()


          const pending =
            await pendingEvents()


          sendJson(
            res,
            200,
            {
              ok:
                true,

              storePath:
                STORE_PATH,

              ledgerPath:
                NEWS_LEDGER_PATH,

              pending:
                pending.length,

              totalEvents:
                store.events.length,

              sources: {
                ttc:
                  Object.keys(
                    store.sources.ttc ||
                    {}
                  )
                    .length,

                fire:
                  Object.keys(
                    store.sources.fire ||
                    {}
                  )
                    .length,

                police:
                  Object.keys(
                    store.sources.police ||
                    {}
                  )
                    .length,
              },

              publishedNews:
                await publishedNewsCounts(),

              updatedAt:
                store.updatedAt,

              syncRunning,
            }
          )
        }
      )


      initialTimeoutId =
        setTimeout(
          () => {
            syncTorontoLiveNewsroom()
              .catch(
                (
                  error
                ) => {
                  console.warn(
                    'LIVE NEWSROOM · INITIAL SYNC FAILED:',
                    error
                  )
                }
              )
          },
          2000
        )


      intervalId =
        setInterval(
          () => {
            syncTorontoLiveNewsroom()
              .catch(
                (
                  error
                ) => {
                  console.warn(
                    'LIVE NEWSROOM · BACKGROUND SYNC FAILED:',
                    error
                  )
                }
              )
          },
          POLL_MS
        )


      server.httpServer?.once(
        'close',
        () => {
          if (
            initialTimeoutId
          ) {
            clearTimeout(
              initialTimeoutId
            )
          }


          if (
            intervalId
          ) {
            clearInterval(
              intervalId
            )
          }
        }
      )
    },
  }
}